float3 crisp,dx,dy,ret1;
float2 zz, uv1,uv2;
float  n1,n2,n3,n4,zv,z, noise, k1, wave;
static float2 sunpos = float2 (0*sin(time/3),-.0);
static float2x2 ofs = float2x2 (texsize.z,0,0,texsize.w)*4;
static float3 suncol = 1+normalize(slow_roam_cos);
float3 cloud (float2 uv_in) {
return (.2+(1+bass_att)*.01/length(uv_in-sunpos)*suncol+(rand_preset.z-.5)*uv_in.y);} 

shader_body {

float2 uv1 = float2(uv.x-0.5+q19,uv.y-0.5);//*aspect.xy;

dx = tex2D(sampler_main,uv+ofs[0]) - tex2D(sampler_main,uv-ofs[0]);
dy = tex2D(sampler_main,uv+ofs[1]) - tex2D(sampler_main,uv-ofs[1]);
zz = float2(dx.b,dy.b);

//clouds
zv = time*.06 ;
zv = time*.08+ .0*GetPixel(uv); //##
uv2 = 3*uv1+ float2(0.02*time,-.05*time);

n1 = tex3D(sampler_noisevol_hq,float3 (uv2.x,uv2.y,zv)).b;
n2 = tex3D(sampler_noisevol_hq,float3 (uv2.x*2,uv2.y*2,zv*2)).b;
n3 = tex3D(sampler_noisevol_hq,float3 (uv2.x*4,uv2.y*4,zv*3)).b;
n4 = tex3D(sampler_noisevol_hq,float3 (uv2.x*8,uv2.y*8,zv*7)).b;
noise = n1 + n2/2 + n3/4 + n4/8 -1;
noise = pow(noise,1);
uv2 = uv1+noise*.1;

//*******************************
ret1 = cloud(uv2);
float k1 = .1;
ret = ret1*k1/2 + GetPixel(uv-.02*zz)*(1-k1)-.01;

float4 noise2 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*0.4 
                     );
float br = ret.x+ret.y+ret.z;
if(br>.1 && br<=.21)ret += (noise2)*.5; 
}

