xn=xp;
yn=yp*sang + zp*cang;
zn=yp*cang - zp*sang;
xp=xn;yp=yn;zp=zn;



zp=zp*2+1.55;

//near clipping plane
a=a*above(zp,0.75);
//a=a*below(zp,8.55);

x=xp/zp+ 0.5;
y=yp/zp * 1.3 + 0.5;

